import numpy as np

from mcf.research.arena.indicators import compute

SIDE = 'long'
GEOM = 'holdtr'
WINDOW = (1300, 1500)          # bar close lo <= tod <= hi (inclusive, as the YAML window)
MIN_ADV = 20000000.0
CONTEXT = ['spy_fo']              # lab context columns (config `context:`), point-in-time per 5-minute bar
CONDS = [
    ('emaDiff', '>=', 0.29),
    ('spy_fo', '>', 0.5),
    ('vwapReclaim', '==', 1.0),
]
LAYERS = ['emaDiff >= 0.29', 'spy_fo > 0.5', 'vwapReclaim == 1', 'window 1300-1500']


def mask(df) -> np.ndarray:
    x = compute(df, names=['emaDiff', 'vwapReclaim'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
    return np.asarray(m, dtype=bool)
